// Package bma is the Go client for the BMA REST API (ADR 0012):
//
//	client := bma.NewClient() // BMA_TOKEN, BMA_BASE_URL, BMA_ORG_ID, BMA_PROJECT_ID
//	client := bma.NewClient(option.WithToken(token), option.WithBaseURL(base),
//		option.WithOrg(org), option.WithProject(project))
//	created, err := client.Agents.Sessions.New(ctx, agentID, bma.AgentSessionNewParams{IdempotencyKey: bma.Ptr("task-1")})
//
// Models are generated by oapi-codegen and services by tools/sdkgen from
// contracts/bma/rest.openapi.yaml and contracts/bma/sdk.resources.yaml.
// Errors are *bma.Error (use errors.As); ErrorCode constants name the
// contract's codes. Lists return a CursorPage and have a ...AutoPaging
// variant; events.Stream returns a Stream whose frames switch on AsAny().
package bma

import (
	"errors"
	"os"
	"strings"

	"github.com/beeos-ai/bma-sdk/internal/apicore"
	"github.com/beeos-ai/bma-sdk/internal/requestconfig"
	"github.com/beeos-ai/bma-sdk/option"
)

const (
	// DefaultBaseURL is the hosted BMA origin; the client adds /api/v1.
	DefaultBaseURL = "https://api.bma.beeos.ai"
	// SDKVersion is the version of this frozen 1.x module; it is not released
	// again. Releases are 2.0 and later (v2/, see tools/check_versions.sh).
	SDKVersion = "1.0.1"
)

// Client is the BMA REST client. Its fields are the top-level resources.
type Client struct {
	resources
	core *apicore.Client
}

// NewClient returns a client. Options set defaults for every request:
// option.WithToken (default BMA_TOKEN; required), option.WithBaseURL (the
// deployment origin; default BMA_BASE_URL, else DefaultBaseURL), option.WithOrg / option.WithProject
// (default BMA_ORG_ID / BMA_PROJECT_ID), option.WithMaxRetries (default 2),
// option.WithRequestTimeout (default 60s; 0 disables it).
// A missing token or an invalid base URL is reported by the first request.
func NewClient(opts ...option.RequestOption) *Client {
	base := strings.TrimSpace(os.Getenv("BMA_BASE_URL"))
	if base == "" {
		base = DefaultBaseURL
	}
	opts = append([]option.RequestOption{option.WithBaseURL(base)}, opts...)
	defaults := requestconfig.Config{
		Token:      strings.TrimSpace(os.Getenv("BMA_TOKEN")),
		Org:        strings.TrimSpace(os.Getenv("BMA_ORG_ID")),
		Project:    strings.TrimSpace(os.Getenv("BMA_PROJECT_ID")),
		MaxRetries: apicore.DefaultMaxRetries,
		Timeout:    apicore.DefaultTimeout,
	}
	cfg, err := requestconfig.Apply(defaults, opts)
	core := &apicore.Client{
		Config:      cfg,
		NewError:    newAPIError,
		StreamError: newStreamError,
		UserAgent:   "bma-sdk-go/" + SDKVersion,
		PathPrefix:  "/api/v1",
		Validate: func(c *requestconfig.Config) error {
			if err != nil {
				return err
			}
			if c.Token == "" {
				return errors.New("bma: token is required; use option.WithToken or set BMA_TOKEN")
			}
			return apicore.CheckBaseURL(c.BaseURL)
		},
	}
	return &Client{resources: newResources(core), core: core}
}

// Ptr returns a pointer to v, for optional fields.
func Ptr[T any](v T) *T { return &v }

// CursorPage is one page of a cursor-paginated list.
type CursorPage[T any] = apicore.CursorPage[T]

// CursorPageAutoPager iterates every item across pages.
type CursorPageAutoPager[T any] = apicore.AutoPager[T]

// Stream is a typed server-sent event stream.
type Stream[T any] = apicore.Stream[T]

// AgentStreamEvent is one frame of Agents.Events.Stream.
type AgentStreamEvent = StreamEventsEvent
